// src/calculators/InternetCalculator.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { internetConfig } from '../config/config';
import InternetSearchForm from './InternetSearchForm';
import InternetResult from './InternetResult';

export default function InternetCalculator() {
  const navigate = useNavigate();
  const [selectedPlan, setSelectedPlan] = useState(null);

  // 공통 설치비용 (1회성 비용, VAT 포함)
  const installationFee = internetConfig.installationFee;

  return (
    <div className="p-6 max-w-3xl mx-auto">
      {/* 타이틀 */}
      <h1 className="text-3xl font-bold mb-8 text-center">
        KT 인터넷 계산기
      </h1>

      {/* 검색 폼 */}
      {!selectedPlan && (
        <InternetSearchForm onSelect={setSelectedPlan} />
      )}

      {/* 결과 및 설치비 안내 */}
      {selectedPlan && (
        <>
          <InternetResult plan={selectedPlan} />

          {/* 설치비 안내: 결합하기 버튼 위에 위치 */}
          <div className="mb-6 text-center text-gray-700">
            신규가입·설치장소 이전 시 설치비 (1회성 비용, VAT 포함):{' '}
            <strong>{installationFee.toLocaleString()}원</strong>
      {/* 경고 문구 */}
      <p className="mt-2 text-base font-bold text-red-500">경고! 본 견적은 대략적인 결과 값 입니다.</p>
          </div>

          {/* 액션 버튼 그룹 */}
          <div className="flex flex-col items-center space-y-4 mb-8">
            <button
              type="button"
              onClick={() => navigate('/bundle')}
              className="w-48 bg-indigo-600 text-white rounded py-2 hover:bg-indigo-700 transition"
            >
              결합하기
            </button>

            <button
              type="button"
              onClick={() => setSelectedPlan(null)}
              className="w-48 bg-blue-500 text-white rounded py-2 hover:bg-blue-600 transition"
            >
              다른 인터넷 검색하기
            </button>
          </div>
        </>
      )}

      {/* 메인으로 돌아가기 */}
      <div className="mt-6 w-full text-center">
        <button onClick={() => navigate('/')} className="w-full px-4 py-2 bg-gray-200 rounded hover:bg-gray-300 transition">
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
